import{_ as e,c as r,o as t,af as o}from"./chunks/framework.r60quYNK.js";const p=JSON.parse('{"title":"成都 - 2025","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/ChengDu.md","filePath":"2_articles/travel_record/ChengDu.md"}'),c={name:"2_articles/travel_record/ChengDu.md"};function l(d,a,i,n,h,_){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="成都-2025" tabindex="-1">成都 - 2025 <a class="header-anchor" href="#成都-2025" aria-label="Permalink to &quot;成都 - 2025&quot;">​</a></h1><h2 id="_6月16日-6月18日-☀️" tabindex="-1">6月16日 - 6月18日 ☀️ <a class="header-anchor" href="#_6月16日-6月18日-☀️" aria-label="Permalink to &quot;6月16日 - 6月18日 ☀️&quot;">​</a></h2><blockquote><p>我和黛黛同学本科毕业旅行的第五站，天府之国！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>因为云南回老家实在太远，所以我们打算一路北上，在成都做个中转，是我们本次毕业旅行的第五站，也是最后一站。</p><h3 id="_6月16日" tabindex="-1">6月16日 <a class="header-anchor" href="#_6月16日" aria-label="Permalink to &quot;6月16日&quot;">​</a></h3><p>早上从香格里拉坐高铁坐了十个小时，高铁上我俩又是一如既往的<code>憨憨选照片</code>，挑了在香格里拉的美照，然后一路看电视剧晚上抵达成都，出门第一感受就是闷热，感觉又回到了南昌一样，这次为了交通方便点酒店直接定在了<code>太古里</code>，到酒店放好东西后出去吃了成都串串，感觉味道和火锅没什么区别，然后在周围散了会步就回去休息啦。</p><h3 id="_6月17日" tabindex="-1">6月17日 <a class="header-anchor" href="#_6月17日" aria-label="Permalink to &quot;6月17日&quot;">​</a></h3><p>这次来成都的主要目的是去<code>成都大熊猫繁殖基地</code>看大熊猫，因为这几年旅游发现商业化的城市几乎没什么意思。所以早上起来后买了水就直接出发大熊猫繁殖基地，然后就在基地逛了一整天，一直到下午的五点多才出去，因为某人一直在等熊猫醒，但是人家不醒哈哈哈。晚上回去后去了成都很有名的蹄花店，价格是真的便宜，而且好吃。</p><h3 id="_6月18日" tabindex="-1">6月18日 <a class="header-anchor" href="#_6月18日" aria-label="Permalink to &quot;6月18日&quot;">​</a></h3><p>因为黛黛要回学校拿双证，所以坐了一大早的高铁出发太原，在太原拿了双证后就结束这次的毕业旅行回家啦~</p><p><code>最后更新时间：2025-08-28 20:23:00</code></p>',12)]))}const u=e(c,[["render",l]]);export{p as __pageData,u as default};
